Register Individual.code:
// Register a new individual.
request('/api/v1/registry/individual', {
  method: 'POST',
  data: {
    given_name: $.data.givenName,
    family_name: $.data.familyName,
    gender: $.data.gender,
    birthdate: $.data.birthdate,
    phone_numbers: [{ phone_no: $.data.phone }],
    addresses: [{ address1: $.data.address }],
  },
});

Register Group.code:
// Register a household.
request('/api/v1/registry/group', {
  method: 'POST',
  data: {
    name: $.data.householdName,
    kind: 'Household',
    members: $.data.memberIds.map(id => ({ individual: id })),
  },
});

Enrol Beneficiary in Program.code:
// Enrol a beneficiary in a program.
request(`/api/v1/program/${$.data.programId}/enroll`, {
  method: 'POST',
  data: { partner_id: $.data.partnerId },
});

Create Payment Batch.code:
// Initiate disbursement for a cycle.
request(`/api/v1/program/${$.data.programId}/cycle/${$.data.cycleId}/disburse`, {
  method: 'POST',
});

Search Individuals.code:
// Search individuals by phone number.
request('/api/v1/registry/individual', {
  method: 'GET',
  query: { phone_no: $.data.phone },
});

Poll Recently Updated Beneficiaries.code:
// Poll program members updated since the last cursor.
request(`/api/v1/program/${$.data.programId}/members`, {
  method: 'GET',
  query: { updated_after: $.cursor.lastRun },
});

Get Payment Status.code:
// Look up a payment by ID.
request(`/api/v1/payments/${$.data.paymentId}`, {
  method: 'GET',
});
